import{_ as t,c as a,o as i,a3 as n,ag as o,ah as r,ai as c,aj as s}from"./chunks/framework.MI-M1z4O.js";const y=JSON.parse('{"title":"SyncAPIM: AI Autonomous API Security Control and Specification Governance Platform","description":"SyncAPIM is an enterprise API security and monitoring agent platform providing real-time API traffic collection, automatic shadow API discovery, OpenAPI 3.0.1 specification drift diagnostics, intelligent web/API attack blocking (WAF), and real-time PII masking.","frontmatter":{"title":"SyncAPIM: AI Autonomous API Security Control and Specification Governance Platform","sidebarTitle":"Overview","description":"SyncAPIM is an enterprise API security and monitoring agent platform providing real-time API traffic collection, automatic shadow API discovery, OpenAPI 3.0.1 specification drift diagnostics, intelligent web/API attack blocking (WAF), and real-time PII masking.","head":[["meta",{"name":"keywords","content":"SyncAPIM, API monitoring, API security, WAF, shadow API detection, OpenAPI 3.0 spec diagnostics, PII masking, JWT validation, SQL injection blocking, SSRF defense, AgentScope Java, PostgreSQL 18.6"}],["meta",{"property":"og:title","content":"SyncAPIM: AI Autonomous API Security Control and Specification Governance Platform"}],["meta",{"property":"og:description","content":"SyncAPIM provides real-time API traffic collection, automatic shadow API discovery, OpenAPI 3.0.1 specification drift diagnostics, intelligent web/API attack blocking (WAF), and real-time PII masking."}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/syncapim/"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/en/syncapim/"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/syncapim/"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/syncapim/"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/syncapim/"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/syncapim/"}]],"sort":1},"headers":[],"relativePath":"en/syncapim/index.md","filePath":"en/syncapim/index.md","lastUpdated":1795293539000}'),d={name:"en/syncapim/index.md"};function l(p,e,m,g,h,f){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="syncapim-ai-autonomous-api-security-control-and-specification-governance-platform" tabindex="-1">SyncAPIM: AI Autonomous API Security Control and Specification Governance Platform <a class="header-anchor" href="#syncapim-ai-autonomous-api-security-control-and-specification-governance-platform" aria-label="Permalink to “SyncAPIM: AI Autonomous API Security Control and Specification Governance Platform”">​</a></h1><blockquote><p><strong>Guide for Non-Developers &amp; Evaluation Teams</strong>: Visit the <a href="https://apim.empasy.io/en/" target="_blank" rel="noopener">SyncAPIM Product Homepage (apim.empasy.io)</a> for an accessible product overview, explore the zero-install interactive UI at the <a href="https://sync.empasy.io/en/products/sync-apim#demo" target="_blank" rel="noopener">Unified Demo Portal</a>, or download brochures and proposal PDFs from the <a href="/en/proposals/">Proposals Archive</a>.</p></blockquote><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>SyncSeries 4-Tier API Security &amp; Control Agent (<code>SYNC_APIM</code>)</strong>: <code>SyncAPIM</code> collects all API traffic flowing in front of microservices and legacy WAS servers in real time to autonomously execute <strong>lexical token grammar fingerprinting (<code>SqlXssLexicalTokenizer</code>)</strong>, <strong>real-time attack pattern detection &amp; pinpoint virtual patching integrated with <code>SyncWatch</code> (<code>ApimDefensePack</code> &amp; <code>SandboxedDefenseEvaluator</code>)</strong>, <strong>kernel eBPF blocking</strong>, <strong>automatic cataloging of unregistered shadow APIs</strong>, <strong>OpenAPI 3.0.1 specification drift diagnostics</strong>, and <strong>dynamic masking across 8 personal/financial PII categories</strong>.</p></div><h2 id="_1-core-architecture-and-technical-standards" tabindex="-1">1. Core Architecture and Technical Standards <a class="header-anchor" href="#_1-core-architecture-and-technical-standards" aria-label="Permalink to “1. Core Architecture and Technical Standards”">​</a></h2><ul><li><strong>Standard Namespace and API</strong>: <code>com.empasy.sync.apim</code> / Canonical API Prefix <code>/api/v1/apim/...</code></li><li><strong>Performance-Isolated 4-JVM Multi-Process Architecture</strong>: <ol><li><code>sync-apim-admin</code> (ports <code>18089</code> / <code>8080</code>): Unified management console REST APIs, time-series statistics batch (<code>ApimTrafficAggregationService</code>), <code>SyncApimAgent</code>, and MCP Server (<code>/api/v1/apim/mcp</code>)</li><li><code>sync-apim-receiver</code> (ports <code>18090</code> / <code>8081</code>, TCP <code>5044</code>/<code>5055</code>): High-speed Lumberjack/Packetbeat packet receiver built on Java 25 Virtual Threads and Redis Stream (<code>job_queue</code>) producer</li><li><code>sync-apim-detector</code> (ports <code>18092</code> / <code>8090</code>): Redis Stream consumer worker, automatic OpenAPI 3.0.1 schema inference, 6-category WAF threat detection, 8-category PII masking, and PostgreSQL 18.6 persistence</li><li><code>sync-apim-gateway</code> (ports <code>18091</code> / <code>8083</code>): Dynamic API blocking filter (<code>BlockedApiFilter</code>) synced in real time with DB/Redis and inline reverse-proxy gateway</li></ol></li><li><strong>AI Autonomous Agent Framework</strong>: Specification drift diagnostics and threat packet forensic explanations powered by <code>AgentScope Java</code> (<code>io.agentscope:agentscope-harness</code>)</li><li><strong>PostgreSQL 18.6 High-Performance Single Storage</strong>: Eliminates heavy external OpenSearch clusters by unifying time-series threat and traffic events (<code>wapf_detect_event</code>) on a PostgreSQL 18.6 <code>JSONB</code> + <code>pg_trgm</code> GIN index engine</li><li><strong>Dynamic RBAC Menu Governance</strong>: Dynamically delivers 11 control screens by role via Vben Admin <code>PermissionModeEnum.BACK</code> mode and the <code>sys_permission</code> single-source-of-truth DB</li></ul><h2 id="_2-key-functional-modules" tabindex="-1">2. Key Functional Modules <a class="header-anchor" href="#_2-key-functional-modules" aria-label="Permalink to “2. Key Functional Modules”">​</a></h2><h3 id="_2-1-api-monitoring-perm-apim-000" tabindex="-1">2.1 API Monitoring (<code>perm-apim-000</code>) <a class="header-anchor" href="#_2-1-api-monitoring-perm-apim-000" aria-label="Permalink to “2.1 API Monitoring (perm-apim-000)”">​</a></h3><ol><li><strong>Host Control (<code>/waf/host</code>)</strong>: Registers protected API gateway, WAS, and web server host inventories and monitors collection agent connection status</li><li><strong>API Catalog (<code>/waf/endpoint</code>)</strong>: Automatically discovers API endpoints from live packet traffic, calculates risk scores, and enforces one-click instant blocking</li><li><strong>API Spec Diagnostics (<code>/waf/api_test</code>)</strong>: Evaluates live request/response schema mismatches (Contract Drift) against OpenAPI 3.0.1 specs and identifies unauthorized shadow APIs</li><li><strong>Traffic Statistics (<code>/waf/api_statistics</code>)</strong>: Provides per-endpoint time-series call volumes, top-called host distributions, and Excel export/import</li><li><strong>Collection Agents (<code>/waf/agent</code>)</strong>: Issues SHA-256 authentication keys for per-domain traffic collection agents and manages target host mappings</li></ol><h3 id="_2-2-api-security-defense-perm-apim-100" tabindex="-1">2.2 API Security Defense (<code>perm-apim-100</code>) <a class="header-anchor" href="#_2-2-api-security-defense-perm-apim-100" aria-label="Permalink to “2.2 API Security Defense (perm-apim-100)”">​</a></h3><ol><li><strong>Threat Detection Logs (<code>/waf/request</code>)</strong>: Forensic inspection of raw threat packets and block status across SQL Injection, XSS, SSRF, RCE, Directory Traversal, and JWT signature tampering</li><li><strong>Security Policies (<code>/waf/policy</code>)</strong>: Operates 7 standard security policy groups—Authentication, Access Control, Data Encryption, Authorization, Network Security, Privacy Protection, and Intrusion Detection (changes sync immediately to Redis cache)</li><li><strong>Detection Rule Management (<code>/waf/rule</code>)</strong>: Defines regex signature patterns and JWT integrity verification options</li><li><strong>Threat Rule Statistics (<code>/waf/rule_statistics</code>)</strong>: Analyzes time-series detection trends and top-triggered rule charts by attack type and severity level</li><li><strong>Sensitive Data Masking (<code>/waf/sensitivity</code>)</strong>: Manages real-time masking rules for 8 PII categories: bank account numbers, email addresses, credit card numbers, national ID numbers, names, passwords, IP addresses, and phone numbers</li><li><strong>Alert Email History (<code>/waf/warning_mails</code>)</strong>: Tracks alert notifications sent to security officers upon high-risk attack blocks or shadow API discoveries</li></ol><h2 id="live-screens-and-core-workflows" tabindex="-1">Live Screens and Core Workflows <a class="header-anchor" href="#live-screens-and-core-workflows" aria-label="Permalink to “Live Screens and Core Workflows”">​</a></h2><h3 id="_1-api-security-control-and-real-time-traffic-threat-dashboard" tabindex="-1">1. API Security Control and Real-Time Traffic &amp; Threat Dashboard <a class="header-anchor" href="#_1-api-security-control-and-real-time-traffic-threat-dashboard" aria-label="Permalink to “1. API Security Control and Real-Time Traffic &amp; Threat Dashboard”">​</a></h3><p>Monitor real-time API traffic trends, threat blocking status, and newly discovered shadow API counts processed by the collection, detection, and blocking pipeline at a glance.</p><p><img src="'+o+'" alt="SyncAPIM API Security Control Unified Dashboard" loading="lazy"></p><h3 id="_2-live-traffic-api-endpoint-catalog-and-shadow-api-detection" tabindex="-1">2. Live-Traffic API Endpoint Catalog and Shadow API Detection <a class="header-anchor" href="#_2-live-traffic-api-endpoint-catalog-and-shadow-api-detection" aria-label="Permalink to “2. Live-Traffic API Endpoint Catalog and Shadow API Detection”">​</a></h3><p>Automatically infer HTTP methods, URI patterns, and request/response payload schemas from live traffic packets to identify unregistered shadow APIs and apply one-click blocking policies.</p><p><img src="'+r+'" alt="SyncAPIM API Endpoint Catalog and Shadow API Management" loading="lazy"></p><h3 id="_3-real-time-web-api-threat-detection-logs-and-attack-packet-forensics" tabindex="-1">3. Real-Time Web &amp; API Threat Detection Logs and Attack Packet Forensics <a class="header-anchor" href="#_3-real-time-web-api-threat-detection-logs-and-attack-packet-forensics" aria-label="Permalink to “3. Real-Time Web &amp; API Threat Detection Logs and Attack Packet Forensics”">​</a></h3><p>Inspect raw attack payloads and risk scores for SQL injection, XSS, SSRF, and remote code execution attempts detected and blocked by grammar fingerprinting and zero-downtime virtual patching rules.</p><p><img src="'+c+'" alt="SyncAPIM Real-Time Threat Detection Logs and Packet Forensics" loading="lazy"></p><h3 id="_4-api-security-policies-and-dynamic-pii-masking-management" tabindex="-1">4. API Security Policies and Dynamic PII Masking Management <a class="header-anchor" href="#_4-api-security-policies-and-dynamic-pii-masking-management" aria-label="Permalink to “4. API Security Policies and Dynamic PII Masking Management”">​</a></h3><p>Control real-time masking rules for 8 personal and financial PII categories—including bank account numbers, credit card numbers, national ID numbers, emails, and phone numbers—as well as per-endpoint security policies with zero downtime.</p><p><img src="'+s+'" alt="SyncAPIM Security Policy and PII Masking Configuration" loading="lazy"></p><hr><h2 id="_3-documentation-guide" tabindex="-1">3. Documentation Guide <a class="header-anchor" href="#_3-documentation-guide" aria-label="Permalink to “3. Documentation Guide”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Document</th><th style="text-align:left;">Key Topics Covered</th><th style="text-align:left;">Link</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>4-JVM Architecture &amp; DB Design</strong></td><td style="text-align:left;">4 independent JVM process isolation architecture, Redis Stream pipeline, and detailed specification of 17 PostgreSQL 18.6 domain tables</td><td style="text-align:left;"><a href="/en/syncapim/architecture">View Architecture →</a></td></tr><tr><td style="text-align:left;"><strong>WAF Threat Detection &amp; PII Masking</strong></td><td style="text-align:left;">Shadow API detection, OpenAPI 3.0.1 Contract Drift comparison audits, 6 attack detection rules, and 8 PII masking policies</td><td style="text-align:left;"><a href="/en/syncapim/waf-and-pii-governance">View Security Governance →</a></td></tr><tr><td style="text-align:left;"><strong>MCP Tools &amp; REST API</strong></td><td style="text-align:left;">6 MCP tools integrated with the <code>SyncVerse</code> control tower (e.g., <code>apim_discover_shadow_apis</code>) and <code>/api/v1/apim</code> REST API reference</td><td style="text-align:left;"><a href="/en/syncapim/mcp-tools">View MCP &amp; API →</a></td></tr><tr><td style="text-align:left;"><strong>Adoption FAQ</strong></td><td style="text-align:left;">Frequently asked questions on air-gapped on-premises deployment, 4-JVM performance isolation, and OpenSearch-replacement architecture</td><td style="text-align:left;"><a href="/en/syncapim/enterprise-faq">View FAQ →</a></td></tr></tbody></table>',26)])])}const P=t(d,[["render",l]]);export{y as __pageData,P as default};
